import * as http from 'node:http';
function main(): void {
const M: any = http;
function t(n: string, f: () => void): void {
  try { f(); console.log(n, 'no throw'); } catch (e: any) { console.log(n, e.name, e.code, e.message); }
}
t('path', () => M.request({ path: '/a b' }));
t('method', () => M.request({ method: 'G E' }));
t('method2', () => M.request({ method: 5 }));
t('host', () => M.request({ hostname: 5 }));
t('host2', () => M.request({ host: {} }));
t('hdrhost', () => M.request({ headers: { host: ['a', 'b'] } }));
t('proto', () => M.request({ protocol: 'https:' }));
t('timeout', () => M.request({ timeout: 'x' }));
t('cb', () => M.request({}, 5));
t('agent4', () => new M.Agent({ scheduling: 'x' }));
t('vhn', () => M.validateHeaderName('a b'));
t('vhv', () => M.validateHeaderValue('a', undefined));
}
